  "steps": [
    {
      "name": "input_guardrail",
      "summary": "Checks the trip request against input guardrails to determine if it should be blocked."
    },
    {
      "name": "booking_agent",
      "summary": "Runs an agent to select a flight and hotel based on destination, days, budget, and preferences."
    },
    {
      "name": "activity_agent",
      "summary": "Runs an agent to retrieve and curate activity recommendations while avoiding excluded activities."
    },
    {
      "name": "generate",
      "summary": "Generates a structured JSON itinerary using the selected flight, hotel, and activity context, incorporating previous critique if retrying."
    },
    {
      "name": "budget_critic",
      "summary": "Reviews the itinerary against the budget and excluded activities, routing to retry if it is over budget or not approved and the retry limit is not reached."
    },
    {
      "name": "output_guardrail",
      "summary": "Validates the final itinerary against output guardrails and records the validation status and reason."
    }
  ],
  "constraints": [
    {
      "applies_to": "step:budget_critic",
      "description": "The agent will only retry generating the itinerary if the number of attempts is less than the maximum retries limit.",
